create type public.health_timeline_event_type as enum ('AI_ASSESSMENT','CONSULTATION','DIAGNOSTIC_TEST','MEDICAL_REPORT','PRESCRIPTION','FOLLOW_UP');
create table public.health_timeline (id uuid primary key default gen_random_uuid(), patient_id uuid not null references public.patients(id) on delete restrict, event_type public.health_timeline_event_type not null, ai_assessment_id uuid references public.symptom_assessments(id) on delete restrict, consultation_id uuid references public.consultations(id) on delete restrict, test_order_id uuid references public.test_orders(id) on delete restrict, medical_report_id uuid references public.medical_reports(id) on delete restrict, prescription_id uuid references public.prescriptions(id) on delete restrict, follow_up_consultation_id uuid references public.consultations(id) on delete restrict, title text not null, summary text, event_at timestamptz not null, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), constraint health_timeline_title_nonempty check (length(trim(title)) > 0), constraint health_timeline_one_source check (((ai_assessment_id is not null)::integer + (consultation_id is not null)::integer + (test_order_id is not null)::integer + (medical_report_id is not null)::integer + (prescription_id is not null)::integer + (follow_up_consultation_id is not null)::integer) = 1));
create unique index health_timeline_ai_source_uidx on public.health_timeline (ai_assessment_id) where ai_assessment_id is not null; create unique index health_timeline_consultation_source_uidx on public.health_timeline (consultation_id) where consultation_id is not null; create unique index health_timeline_test_order_source_uidx on public.health_timeline (test_order_id) where test_order_id is not null; create unique index health_timeline_report_source_uidx on public.health_timeline (medical_report_id) where medical_report_id is not null; create unique index health_timeline_prescription_source_uidx on public.health_timeline (prescription_id) where prescription_id is not null; create unique index health_timeline_follow_up_source_uidx on public.health_timeline (follow_up_consultation_id) where follow_up_consultation_id is not null; create index health_timeline_patient_event_idx on public.health_timeline (patient_id, event_at desc);
alter table public.health_timeline enable row level security;
create or replace function public.set_health_timeline_updated_at() returns trigger language plpgsql security invoker set search_path = public as $$ begin new.updated_at = now(); return new; end; $$; drop trigger if exists health_timeline_set_updated_at on public.health_timeline; create trigger health_timeline_set_updated_at before update on public.health_timeline for each row execute function public.set_health_timeline_updated_at();
create or replace function public.validate_health_timeline_source() returns trigger language plpgsql security invoker set search_path = public as $$ declare v_patient_id uuid; begin if new.event_type = 'AI_ASSESSMENT' then if new.ai_assessment_id is null then raise exception using errcode = '23514', message = 'AI assessment source is required'; end if; select patient_id into v_patient_id from public.symptom_assessments where id = new.ai_assessment_id; elsif new.event_type = 'CONSULTATION' then if new.consultation_id is null then raise exception using errcode = '23514', message = 'Consultation source is required'; end if; select patient_id into v_patient_id from public.consultations where id = new.consultation_id; elsif new.event_type = 'DIAGNOSTIC_TEST' then if new.test_order_id is null then raise exception using errcode = '23514', message = 'Test order source is required'; end if; select patient_id into v_patient_id from public.test_orders where id = new.test_order_id; elsif new.event_type = 'MEDICAL_REPORT' then if new.medical_report_id is null then raise exception using errcode = '23514', message = 'Medical report source is required'; end if; select patient_id into v_patient_id from public.medical_reports where id = new.medical_report_id; elsif new.event_type = 'PRESCRIPTION' then if new.prescription_id is null then raise exception using errcode = '23514', message = 'Prescription source is required'; end if; select patient_id into v_patient_id from public.prescriptions where id = new.prescription_id; elsif new.event_type = 'FOLLOW_UP' then if new.follow_up_consultation_id is null then raise exception using errcode = '23514', message = 'Follow-up source is required'; end if; select patient_id into v_patient_id from public.consultations where id = new.follow_up_consultation_id; end if; if v_patient_id is null then raise exception using errcode = '22023', message = 'Timeline source not found'; end if; if new.patient_id <> v_patient_id then raise exception using errcode = '23514', message = 'Timeline patient does not match its source record'; end if; return new; end; $$; drop trigger if exists health_timeline_validate_source on public.health_timeline; create trigger health_timeline_validate_source before insert or update on public.health_timeline for each row execute function public.validate_health_timeline_source();
create or replace function public.sync_health_timeline_event(p_patient_id uuid, p_event_type public.health_timeline_event_type, p_title text, p_summary text, p_event_at timestamptz, p_ai_assessment_id uuid default null, p_consultation_id uuid default null, p_test_order_id uuid default null, p_medical_report_id uuid default null, p_prescription_id uuid default null, p_follow_up_consultation_id uuid default null) returns public.health_timeline language plpgsql security definer set search_path = public as $$ declare v_event public.health_timeline; v_user_patient_id uuid; begin if auth.uid() is null then raise exception using errcode = '42501', message = 'Authentication required'; end if; select id into v_user_patient_id from public.patients where user_id = auth.uid(); if not public.is_admin() and (v_user_patient_id is null or v_user_patient_id <> p_patient_id) then raise exception using errcode = '42501', message = 'Only the patient or an administrator may synchronize this timeline'; end if; select * into v_event from public.health_timeline where (p_event_type = 'AI_ASSESSMENT' and ai_assessment_id = p_ai_assessment_id) or (p_event_type = 'CONSULTATION' and consultation_id = p_consultation_id) or (p_event_type = 'DIAGNOSTIC_TEST' and test_order_id = p_test_order_id) or (p_event_type = 'MEDICAL_REPORT' and medical_report_id = p_medical_report_id) or (p_event_type = 'PRESCRIPTION' and prescription_id = p_prescription_id) or (p_event_type = 'FOLLOW_UP' and follow_up_consultation_id = p_follow_up_consultation_id) limit 1; if v_event.id is null then insert into public.health_timeline (patient_id, event_type, ai_assessment_id, consultation_id, test_order_id, medical_report_id, prescription_id, follow_up_consultation_id, title, summary, event_at) values (p_patient_id, p_event_type, p_ai_assessment_id, p_consultation_id, p_test_order_id, p_medical_report_id, p_prescription_id, p_follow_up_consultation_id, p_title, p_summary, p_event_at) returning * into v_event; else update public.health_timeline set title = p_title, summary = p_summary, event_at = p_event_at where id = v_event.id returning * into v_event; end if; return v_event; end; $$; revoke all on function public.sync_health_timeline_event(uuid, public.health_timeline_event_type, text, text, timestamptz, uuid, uuid, uuid, uuid, uuid, uuid) from public; grant execute on function public.sync_health_timeline_event(uuid, public.health_timeline_event_type, text, text, timestamptz, uuid, uuid, uuid, uuid, uuid, uuid) to authenticated;
create policy health_timeline_select_patient on public.health_timeline for select to authenticated using (exists (select 1 from public.patients p where p.id = patient_id and p.user_id = auth.uid())); create policy health_timeline_select_doctor on public.health_timeline for select to authenticated using (exists (select 1 from public.consultations c join public.doctors d on d.id = c.doctor_id where c.id = consultation_id and d.user_id = auth.uid() and d.approval_status = 'APPROVED') or exists (select 1 from public.test_orders o join public.doctors d on d.id = o.doctor_id where o.id = test_order_id and d.user_id = auth.uid() and d.approval_status = 'APPROVED') or exists (select 1 from public.prescriptions pr join public.doctors d on d.id = pr.doctor_id where pr.id = prescription_id and d.user_id = auth.uid() and d.approval_status = 'APPROVED') or exists (select 1 from public.medical_reports mr join public.test_orders o on o.id = mr.test_order_id join public.doctors d on d.id = o.doctor_id where mr.id = medical_report_id and d.user_id = auth.uid() and d.approval_status = 'APPROVED')); create policy health_timeline_select_admin on public.health_timeline for select to authenticated using (public.is_admin()); create policy health_timeline_insert_admin on public.health_timeline for insert to authenticated with check (public.is_admin()); create policy health_timeline_update_admin on public.health_timeline for update to authenticated using (public.is_admin()) with check (public.is_admin()); create policy health_timeline_delete_admin on public.health_timeline for delete to authenticated using (public.is_admin());
